var LOCALE_ORDER = LOCALES.map(function (l) { return l.code; });

function normalizeLocale(raw) {
  if (!raw) return "";
  var v = String(raw).trim().toLowerCase();
  if (v === "zh-hans" || v === "zh-cn") v = "zh";
  if (v === "pt-br") v = "pt";
  var base = v.split(/[-_]/)[0];
  return LOCALE_ORDER.indexOf(base) >= 0 ? base : (LOCALE_ORDER.indexOf(v) >= 0 ? v : "");
}

function detectLocale() {
  var saved = "";
  try { saved = localStorage.getItem("artecraft.locale") || ""; } catch (e) {}
  var cand = normalizeLocale(saved) || normalizeLocale(navigator.language) ||
             normalizeLocale((navigator.languages || []).join(",").split(",")[0]) || "en";
  return cand;
}

function localeMeta(code) {
  for (var i = 0; i < LOCALES.length; i++) if (LOCALES[i].code === code) return LOCALES[i];
  return LOCALES[0];
}

function tf(code, key, vars) {
  var arr = DICT[key];
  var str = "";
  if (arr) {
    var idx = LOCALE_ORDER.indexOf(code);
    str = arr[idx >= 0 ? idx : 0] || arr[0] || "";
  }
  if (!str) str = (DICT[key] && DICT[key][0]) || key;
  if (vars) {
    Object.keys(vars).forEach(function (k) {
      str = str.split("{" + k + "}").join(String(vars[k]));
    });
  }
  return str;
}

